sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var subcat = current.getValue('subcategory');
    if (!subcat) {
        return;
    }
    subcat = String(subcat);

    // 1. Mandatory Single Admission
    // Facilities: AC (131), Plumbing (132), Electrical (133)
    // Hygiene: Room cleaning (102), Linen (103)
    // Food: Meal delivery (111), Incorrect diet (112)
    // General: Clinical care (145)
    var mandatoryAdmissionSubcats = ['131', '132', '133', '102', '103', '111', '112', '145'];
    if (mandatoryAdmissionSubcats.indexOf(subcat) > -1) {
        if (current.admission.nil()) {
            gs.addErrorMessage('Validation Error: Admission reference is required for this grievance subcategory.');
            current.setAbortAction(true);
            return;
        }
    }

    // 2. Either/Or: Doctor Communication (121), Lack of Empathy (125)
    // Must have at least one: Admission OR Appointment
    if (subcat === '121' || subcat === '125') {
        if (current.admission.nil() && current.appointment.nil()) {
            gs.addErrorMessage('Validation Error: At least one reference (Admission or Appointment) is required for this grievance subcategory.');
            current.setAbortAction(true);
            return;
        }
    }

    // 3. Either/Or: Billing / Admin Misconduct (123)
    // Must have at least one: Admission OR Invoice
    if (subcat === '123') {
        if (current.admission.nil() && current.invoice.nil()) {
            gs.addErrorMessage('Validation Error: At least one reference (Admission or Invoice) is required for this grievance subcategory.');
            current.setAbortAction(true);
            return;
        }
    }

    // 4. Mandatory Appointment: Appointment / Scheduling Issue (142)
    if (subcat === '142') {
        if (current.appointment.nil()) {
            gs.addErrorMessage('Validation Error: Appointment reference is required for this grievance subcategory.');
            current.setAbortAction(true);
            return;
        }
    }

    // 5. Mandatory Lab Test Result: Diagnostic Report Delay (143)
    if (subcat === '143') {
        if (current.lab_test_result.nil()) {
            gs.addErrorMessage('Validation Error: Lab Test Result reference is required for this grievance subcategory.');
            current.setAbortAction(true);
            return;
        }
    }

    // 6. Mandatory Invoice: Billing & Insurance / TPA Query (144)
    if (subcat === '144') {
        if (current.invoice.nil()) {
            gs.addErrorMessage('Validation Error: Invoice reference is required for this grievance subcategory.');
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
